from orders.db import get_conn


def get_order(order_id):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, customer_id, total_cents, status FROM orders WHERE id = :id",
            {"id": order_id},
        )
    finally:
        conn.close()
    if not rows:
        return None
    return rows[0]


def list_orders_for_customer(customer_id):
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT id, total_cents, status FROM orders WHERE customer_id = :customer_id ORDER BY id",
            {"customer_id": customer_id},
        )
    finally:
        conn.close()
    return rows


def create_order(customer_id, total_cents):
    conn = get_conn()
    try:
        rows = conn.execute(
            "INSERT INTO orders (customer_id, total_cents, status) VALUES (:customer_id, :total_cents, 'new') RETURNING id",
            {"customer_id": customer_id, "total_cents": total_cents},
        )
    finally:
        conn.close()
    return rows[0]["id"]
